    if not isinstance(arr, list):
        raise TypeError("Input must be a list of integers.")

    # If n is not provided, use the length of the array
    if n is None:
        n = len(arr)

    # Check if n is an integer
    if not isinstance(n, int):
        raise TypeError("The length of the list must be an integer.")

    # Check if the array is empty
    if n == 0:
        return None

    # Check if all elements in the array are integers
    for i in range(n):
        if not isinstance(arr[i], int):
            raise TypeError("All elements in the list must be integers.")

    # Create a dictionary to store the count of each element
    count_dict = {}

    # Iterate over each element in the array
    for i in range(n):
        num = arr[i]
        # If the element is already in the dictionary, increment its count
        if num in count_dict:
            count_dict[num] += 1
        # If the element is not in the dictionary, add it with a count of 1
        else:
            count_dict[num] = 1

    # Iterate over the dictionary to find the element with an odd count
    for num, count in count_dict.items():
        if count % 2 != 0:
            return num

    # If no element with an odd occurrence is found, return None
    return None

